import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"41、【損】 兌下艮上","description":"周易尚氏學 - 41、【損】 兌下艮上","frontmatter":{"title":"41、【損】 兌下艮上","description":"周易尚氏學 - 41、【損】 兌下艮上"},"headers":[],"relativePath":"classics/shangshi/046.md","filePath":"classics/shangshi/046.md"}'),s={name:"classics/shangshi/046.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_41、【損】-兌下艮上" tabindex="-1">41、【損】 兌下艮上 <a class="header-anchor" href="#_41、【損】-兌下艮上" aria-label="Permalink to “41、【損】 兌下艮上”">​</a></h1><p>貞我悔彼。以我之陽。益彼之上。故曰損。歸藏作員。朱彝尊謂即損卦。然歸藏以益為誠。則此未必取義於損。按員古作雲。商頌景員維何。箋員古文作雲。以此例之。歸藏必原作雲也。說文。雲山川氣也。象迴轉形。後人加雨作雲。是雲即雲字。卦上艮下兌。說卦由澤通氣。氣即雲。中互坤。坤正為雲。卦二至上正反震。震為出。雲出澤中。至上而反。正迴轉之形。與說文合。與卦象合。六爻皆有應。故曰有孚。二陽遇陰。乾元通。故曰元吉。可貞。言二不宜升毛再損也。利有攸往謂上也。上九下乘重陰。頤曰利涉大川。利涉即利往也。爾雅釋詁。曷止也。而曷與曷（左心）通。詩大雅。汽可小曷（左心）。傳曷（左心）息也。息止義同。故集韻雲。曷（左心）或作曷也。而曷（左心）與甜通。詩甘棠篇。召伯所矩。釋文。慈本又作曷（左心）。曷之用言憩息之時也。上卦艮。故云憩。震為簋。坤數二。故曰二簋。況為亨。亨饗通。左傳成十二年享以訓恭儉。釋文享本亦作饗。又莊四年止而饗之。周語。大臣饗其祿。注皆訓饗為食。易之用二簋可用享。言當休暇之時。可以二簋為亨。二籃雖儉。然處損時。亦可也。清儒承荀氏舊說。見言簋即以為祭宗廟。侈陳禮制。豈知儀禮公食大夫扎。宰夫啟簋。詩秦風於我乎食四簋。凡宴享皆用簋。非必祭宗廟始用也。且於易義之謂何矣。崔憬以曷為何。荀爽等只說二簋可用享。不及曷義。於是清儒如惠棟焦循張惠言孫星衍等。亦不釋曷義。只一姚配中襲崔憬說。疑非也。</p><p>彖曰。損。損下益上。其道上行。損而有孚。元吉。無咎。可貞。利有攸往。曷之用。二簋可用享。二簋應有時。損剛益柔有時。損益盈虛。與時偕行。</p><p>貞我悔彼。內與外。上與下。其親疏迥不相同。故夫以內陽益外。則我損矣。上下即內外也。泰三往上。故曰其道上行。震為應。二至四震。乃上卦震覆。若反聲相應者。故曰二簋應。與中孚之鶴鳴子和理同也。二簋應有時。言時當曷（左心）息。用二簋享。正與時應也。泰極還否。損者泰之終。否之始。損剛益柔有時者。按卦氣。損為七月卦。時已當否。陽日減。陰日增。正損剛益柔之時。不可不預知也。時當益則益。時當損則損。益則盈。損則虛。乾盈坤虛。應時而行。所謂窮則變。變則通也。</p><p>象曰。山下有澤。損。君子以懲忿窒欲。</p><p>震為決躁。為武人。故為忿。乃上卦震覆為艮。艮止故曰懲忿。二至上正覆震。震為口有爭食象。坤閉故曰窒慾。學易之君子。因以取法焉。</p><p>初九。已事這往。無咎。酌損之。</p><p>已虞作祀。晁氏雲。巳古文祀宇。按金文沈子它敦銘。用饗響已公。已公即祀公。初應在四。四震為祭祀。兌為晌。遺速也。祀事遺往者。言宜往應四也。當位故無咎。所應為陰。故曰酌損。</p><h3 id="象曰。已事遙往。尚合志也。" tabindex="-1">象曰。已事遙往。尚合志也。 <a class="header-anchor" href="#象曰。已事遙往。尚合志也。" aria-label="Permalink to “象曰。已事遙往。尚合志也。”">​</a></h3><p>尚上同。上謂四。初四婚媾。故曰合志。四坤為志。其用卦變以坎為志者。非也。</p><p>九二。利貞。徵兇。弗損。益之。</p><p>三已損矣。二不宜再損。故利於貞定也。震為徵。二陽臨重陰。更利於徵。然二往五則下愈損。故徵兇也。弗損者。即貞於二不動。不再損下也。弗損即益二矣。故曰益之。夫貞我侮彼。泰三陽三陰。而陽全在我。此所以為泰也。損我一陽以益外。已非善徵。若損之不已。則成否矣。否天地閉。賢人隱。故於二爻著以為戒。曰利貞。曰徵兇。舊解惟王弼能識二之不宜往五。謂剛全上則剝道成。若虞翻則謂二不徵之五則兇。故反經為說。豈知二陽得五陰為應。利往誠為常例。獨損二因其利往。再損內也。故因以為戒。乃後世如惠棟張惠言等。多祖述其說。獨姚配中識虞義之反經。乃又以利貞為之正。二之正成陰。陰與陰不相應。故徵兇。仍以卦變為穿鑿。然則不獨易象失傳。易理之失傳更甚也。</p><h3 id="象曰。九二利貞。中以為志也。" tabindex="-1">象曰。九二利貞。中以為志也。 <a class="header-anchor" href="#象曰。九二利貞。中以為志也。" aria-label="Permalink to “象曰。九二利貞。中以為志也。”">​</a></h3><p>中謂二。言志貞於二。不前進也。故曰中以為志。舊解無不誤者。</p><p>六三。三人行則損一人。一人行則得其友。</p><p>乾為人。泰三陽原為三人。今成兌。損一人矣。損三以益上。上乘重陰。陽以陰為友。故曰一人行則得其友。友謂四五。舊解以下應兌為友。故於三則疑之故。無有通者。</p><h3 id="象曰。一人行三則疑也。" tabindex="-1">象曰。一人行三則疑也。 <a class="header-anchor" href="#象曰。一人行三則疑也。" aria-label="Permalink to “象曰。一人行三則疑也。”">​</a></h3><p>三陽上行則成否。否上九為四五所阻格。所謂敵也。敵則相疑相忌。而不相友矣。釋得友之故也。易於陰陽相遇為朋友之故。言之可謂明白矣。乃自荀虞以來。以兌二陽房二陰為朋友。相承至今。豈知陽遇陽陰遇陰。艮謂之敵應。中孚謂之得敵哉。</p><p>六四。損其疾。使遄有喜。無咎。</p><p>坤為疾。四得陽應。故曰損其疾。遄往也。坤為憂。乾為喜。使遺有喜者。言往得陽應而喜也。坤疾象失傳。舊解故多不當。</p><h3 id="象曰。損其疾。亦可喜也。疾損故可喜。" tabindex="-1">象曰。損其疾。亦可喜也。疾損故可喜。 <a class="header-anchor" href="#象曰。損其疾。亦可喜也。疾損故可喜。" aria-label="Permalink to “象曰。損其疾。亦可喜也。疾損故可喜。”">​</a></h3><p>六五。或益之十朋之龜。弗克違。元吉。</p><p>艮為龜。漢書食貨志注。蘇林曰。兩貝為朋。朋值二百一十六。元龜十朋。艮為朋友。坤數十。故曰十朋之龜。言陽在上五得承之。若大寶之益也。陰順陽。故曰弗克違。五卦位最尊尊。故曰元吉。艮龜象失傳。侯果謂內柔外剛龜之象。豈知艮即為龜。</p><h3 id="象曰。六五元吉。自上佑也" tabindex="-1">象曰。六五元吉。自上佑也 <a class="header-anchor" href="#象曰。六五元吉。自上佑也" aria-label="Permalink to “象曰。六五元吉。自上佑也”">​</a></h3><p>上為陽。五承之。故曰自上佑。估福也。釋文或作佑。無言漢人作右者。惠棟擅改之。後學盲從之。於是集解之文遂亂矣。不可不知。又自虞翻以來。皆以二益五為說。清孺皆宗之。不椎與象傳背。且與經背。經於九二言徵兇。言利貞。言弗損。則二固不往五。況象傳明言自上信。則十朋之龜指上也。弗克違。言五承上也。則以二益五為說者。其誤益明矣。</p><p>上九。弗損益之。無咎。貞吉。利有攸往。得巨無家。</p><p>上之三則上損矣。不動則益上。故曰弗損益之。貞吉者卜問吉也。上乘重陰，故利有攸往。與頤上九同。坤為臣。上據坤。是得臣為助也。三者上九之家。上既得臣為助。即不返三。故曰得臣無家。盲公而忘私也。</p><h3 id="象曰。弗損益之。大得志也" tabindex="-1">象曰。弗損益之。大得志也 <a class="header-anchor" href="#象曰。弗損益之。大得志也" aria-label="Permalink to “象曰。弗損益之。大得志也”">​</a></h3><p>坤為志。上據坤。陽乘陰。故曰大得志。舊解皆以上返三為說。非。</p>',29)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
